  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 How Scientists Ask and Test Questions$j$, $j${"readings": [{"title": "Proverbs 25 (King James Version)", "url": "/portal/bible/Proverbs/25"}], "body": "Biology is the study of living things. Science is a way of learning about the natural world by asking questions that can be tested with evidence. Proverbs 25:2 says, It is the glory of God to conceal a thing: but the honour of kings is to search out a matter.\n\nThe scientific method is a flexible set of practices, not a rigid list. Scientists usually do these things:\nObserve something and ask a testable question.\nResearch what is already known.\nForm a hypothesis, which is a testable explanation or prediction.\nDesign an experiment with a procedure that others can repeat.\nCollect and analyze data.\nDraw a conclusion from the evidence and share the results so others can check them.\n\nA good hypothesis can be tested and could be shown wrong. Example: If bean plants receive more light each day, then they will grow taller. A statement such as plants are happiest in sunshine cannot be measured, so it is not a scientific hypothesis.\n\nScience and nonscience differ. Science depends on evidence that can be observed or measured and repeated by others. Questions about beauty, purpose or worship are important, but they are not answered by a laboratory test.\n\nA theory in science is a well tested explanation supported by a large body of evidence, such as cell theory. A scientific law describes a pattern that always occurs, such as the law of conservation of mass.\n\nYour task: (1) Write a testable hypothesis about how fertilizer affects plant growth. (2) Explain why the statement chocolate is the best flavor is not a scientific hypothesis. (3) Tell the difference between a hypothesis and a theory.\n\nFlorida standards: SC.912.N.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.N.1.1", "script": "Welcome to Biology 1. I am Dr. Alex L. Jenkins Sr., and I am glad you are here. Listen, biology is the study of life, and there is no better place to see the wisdom of God than in the living things around us. Proverbs twenty five and two says, It is the glory of God to conceal a thing: but the honour of kings is to search out a matter. Today you learn how to search out a matter like a scientist.\n\nNow watch this. Science is a way of learning about the natural world by asking questions that can be tested with evidence. The steps are flexible, but they usually go like this. You observe something and ask a question. You research what is already known. You form a hypothesis, a testable explanation or prediction. You design an experiment that others could repeat. You collect and analyze data. And you draw a conclusion and share it so others can check your work.\n\nLook at this. A good hypothesis can be tested and could be shown wrong. If bean plants receive more light each day, then they will grow taller. You can measure that. But the statement, plants are happiest in sunshine, cannot be measured, so it is not a scientific hypothesis.\n\nScience and nonscience are different. Science depends on evidence that can be observed or measured and repeated. Questions about beauty, purpose and worship matter greatly, but they are not answered with a laboratory test, and a wise student knows which tool fits which question.\n\nAlso learn two words. A theory in science is a well tested explanation supported by a large body of evidence, like cell theory. A law describes a pattern that always occurs, like the conservation of mass.\n\nYour task today. Write a testable hypothesis about fertilizer and plant growth. Explain why chocolate is the best flavor is not scientific. And tell the difference between a hypothesis and a theory. Take the four question check when you finish.\n\nHonest searching honors the Creator. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 How Scientists Ask and Test Questions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Variables, Data and Evidence$j$, $j${"readings": [{"title": "Psalm 19 (King James Version)", "url": "/portal/bible/Psalms/19"}], "body": "A fair experiment changes one thing at a time so the results mean something.\n\nIndependent variable: the one factor you change on purpose (for example, the amount of light).\nDependent variable: the factor you measure to see the effect (for example, plant height).\nControlled variables (constants): the factors you keep the same (soil, water, pot size, temperature).\nControl group: the group that does not receive the treatment, used for comparison.\nSample size: the number of subjects tested. More trials make the results more trustworthy.\n\nData can be quantitative (numbers, such as 12 centimeters) or qualitative (descriptions, such as dark green leaves). Tables and graphs help us see patterns. On a graph, the independent variable goes on the x axis and the dependent variable goes on the y axis.\n\nExample: Four groups of 10 bean plants get 0, 4, 8 and 12 hours of light. After two weeks the average heights are 3, 9, 15 and 17 centimeters. Light is the independent variable and height is the dependent variable. The 0 hour group is the control. Height rises with more light, but the gain from 8 to 12 hours is small, so growth may level off.\n\nA conclusion must be supported by the data. We say the data support or do not support the hypothesis. Be honest about errors, such as measuring mistakes, and about limits, such as a small sample. Averages: add the values and divide by how many there are.\n\nYour task: (1) In the example, find the average height gain from 0 to 8 hours. (2) Name two controlled variables you would keep the same. (3) Explain why one trial is not enough.\n\nFlorida standards: SC.912.N.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.N.1.1", "script": "Hello again. This is Dr. Jenkins. Listen, a fair test is a wise test, and Proverbs eleven and one says, A false balance is abomination to the LORD: but a just weight is his delight. In science, fairness means changing only one thing at a time.\n\nNow watch this. The independent variable is the one thing you change on purpose, like the amount of light. The dependent variable is what you measure to see the effect, like plant height. The controlled variables are everything you keep the same, such as soil, water, pot size and temperature. And the control group is the group that does not get the treatment, so you have something to compare against. Sample size matters too. More trials make your results more trustworthy.\n\nLook at this. Data can be quantitative, meaning numbers like twelve centimeters, or qualitative, meaning descriptions like dark green leaves. Tables and graphs help us see patterns. On a graph the independent variable goes on the x axis and the dependent variable goes on the y axis.\n\nHere is an example. Four groups of ten bean plants get zero, four, eight and twelve hours of light. The average heights after two weeks are three, nine, fifteen and seventeen centimeters. Light is independent. Height is dependent. The zero hour group is the control. Height rises with light, but the gain from eight to twelve hours is small, so growth may be leveling off.\n\nA conclusion must be supported by the data. We say the data support or do not support the hypothesis. And we are honest about errors, like measuring mistakes, and about limits, like a small sample. To find an average, add the values and divide by how many there are.\n\nYour task today. Find the average height gain from zero to eight hours. Name two controlled variables. And explain why one trial is not enough. Take the four question check when you finish.\n\nHonest numbers are a form of integrity. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Variables, Data and Evidence$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Water: The Molecule of Life$j$, $j${"readings": [{"title": "Genesis 1 (King James Version)", "url": "/portal/bible/Genesis/1"}], "body": "Matter is made of atoms. Two or more atoms joined by bonds make a molecule. The most important molecule for life is water, H2O. Psalm 104:24 says, O LORD, how manifold are thy works! in wisdom hast thou made them all: the earth is full of thy riches.\n\nA water molecule is polar: the oxygen end has a slight negative charge and the hydrogen ends have a slight positive charge. The positive end of one molecule is attracted to the negative end of another, forming a hydrogen bond. These bonds explain the special properties of water.\n\nCohesion: water molecules stick to each other. This causes surface tension, which lets some insects walk on water.\nAdhesion: water sticks to other surfaces. Cohesion and adhesion together pull water up the thin tubes of plants (capillary action).\nHigh specific heat: water absorbs much heat before its temperature rises, which keeps oceans, lakes and our bodies steady.\nIce floats: water is less dense as a solid, so ice forms on top and lakes do not freeze solid, protecting life below.\nUniversal solvent: many substances dissolve in water, so it carries nutrients and wastes in blood and cells.\n\nThe pH scale runs from 0 to 14. A pH below 7 is acidic, 7 is neutral and above 7 is basic. Each step is a factor of 10. Buffers help keep the pH of blood near 7.4. Cells depend on a stable pH.\n\nYour task: (1) Explain how hydrogen bonds cause surface tension. (2) Tell why ice floating protects fish in winter. (3) How many times more acidic is pH 3 than pH 5?\n\nFlorida standards: SC.912.L.18.12.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.18.12", "script": "Welcome back. Dr. Jenkins here. Listen, the most important molecule for life is one you drink every day. Psalm one hundred four and twenty four says, O LORD, how manifold are thy works! in wisdom hast thou made them all: the earth is full of thy riches. Today we look at water.\n\nMatter is made of atoms, and atoms joined by bonds make molecules. Water is H two O. Now watch this. The oxygen end of the molecule has a slight negative charge, and the hydrogen ends have a slight positive charge. We call that polar. The positive end of one water molecule is attracted to the negative end of another, and that attraction is called a hydrogen bond.\n\nLook at what hydrogen bonds do. Cohesion means water sticks to water, giving surface tension, so some insects can walk on a pond. Adhesion means water sticks to other surfaces, and together with cohesion it pulls water up the thin tubes in a plant. Water has a high specific heat, so it takes a lot of heat to change its temperature, and that keeps oceans and our bodies steady. Ice is less dense than liquid water, so it floats, and lakes freeze from the top, protecting the fish below. And water is the universal solvent, carrying nutrients and wastes in our blood and cells.\n\nNow the pH scale. It runs from zero to fourteen. Below seven is acidic, seven is neutral, and above seven is basic. Each step is a factor of ten. Buffers keep the pH of your blood near seven point four, because cells need a steady environment.\n\nYour task today. Explain how hydrogen bonds cause surface tension. Tell why floating ice protects fish. And find how many times more acidic pH three is than pH five. Take the four question check when you finish.\n\nEvery drop shows careful design. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Water: The Molecule of Life$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 The Four Biomolecules of Life$j$, $j${"readings": [{"title": "Psalm 104 (King James Version)", "url": "/portal/bible/Psalms/104"}], "body": "Living things are built from four main groups of large molecules, called macromolecules or biomolecules. Each is made of smaller units, called monomers, joined into long chains called polymers. Psalm 139:14 says, I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well.\n\nCarbohydrates: made of carbon, hydrogen and oxygen. The monomer is a simple sugar such as glucose. Functions: quick energy and structure. Examples: sugar, starch (plant storage), glycogen (animal storage) and cellulose (plant cell walls).\nLipids: fats, oils, waxes and phospholipids. They do not mix with water. Functions: long term energy storage, insulation, and cell membranes.\nProteins: the monomer is the amino acid, and there are 20 kinds. A chain folds into a specific shape that decides its job. Functions: enzymes, muscles, transport, defense and structure.\nNucleic acids: DNA and RNA. The monomer is the nucleotide. Function: store and pass on the instructions for building proteins.\n\nEnzymes are proteins that speed up chemical reactions by lowering the energy needed to start them. An enzyme works on a specific substrate at the active site, like a key fitting a lock. High heat or the wrong pH can denature an enzyme, changing its shape so it stops working. Enzymes are not used up.\n\nTests: iodine turns dark blue black with starch. Benedict's solution turns orange or red with simple sugars when heated.\n\nYour task: (1) Match each group to its monomer. (2) Explain why changing the shape of an enzyme stops it from working. (3) Name one function of a lipid.\n\nFlorida standards: SC.912.L.18.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.18.1", "script": "Welcome back. This is Dr. Jenkins. Listen, you are made of four kinds of large molecules, and Psalm one thirty nine and fourteen says, I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well. Today we see how wonderfully.\n\nNow watch this. These large molecules are built from small units called monomers, joined into long chains called polymers. Carbohydrates are made of carbon, hydrogen and oxygen. The monomer is a simple sugar like glucose. They give quick energy and structure. Sugar, starch, glycogen and cellulose are examples. Lipids are fats, oils, waxes and phospholipids. They do not mix with water, and they store long term energy, insulate, and form cell membranes.\n\nLook at proteins. The monomer is the amino acid, and there are twenty kinds. A chain folds into a shape, and the shape decides the job. Proteins act as enzymes, build muscle, carry materials and defend the body. Nucleic acids are DNA and RNA. The monomer is the nucleotide, and they store and pass on the instructions for making proteins.\n\nEnzymes are proteins that speed up reactions by lowering the energy needed to start them. An enzyme works on a specific substrate at its active site, like a key fitting a lock. Too much heat or the wrong pH can denature an enzyme, which means it changes shape and stops working. Enzymes are not used up.\n\nTwo simple tests. Iodine turns dark blue black with starch. Benedict's solution turns orange or red with simple sugars when heated.\n\nYour task today. Match each group to its monomer. Explain why a changed shape stops an enzyme. And name a function of a lipid. Take the four question check when you finish.\n\nFearfully and wonderfully made. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 The Four Biomolecules of Life$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Design a Fair Experiment$j$, $j${"prompt": "Design a fair experiment about a living thing. Write complete sentences and label each part. Proverbs 25:2 says, It is the glory of God to conceal a thing: but the honour of kings is to search out a matter. Search out your matter carefully.\n\nPart 1: State a testable question and a hypothesis about how one factor affects seeds, plants, yeast or another safe living thing.\nPart 2: Name the independent variable, the dependent variable, at least three controlled variables and the control group.\nPart 3: Write a numbered procedure that another student could repeat, including how many trials you will run.\nPart 4: Make a data table with blank rows for your results and tell what kind of graph you would draw and what goes on each axis.\nPart 5: Tell the four biomolecules and name one biomolecule involved in your experiment (for example, an enzyme in yeast or starch in a seed). Explain its role in one or two sentences.\nPart 6: Explain two ways your results could be wrong and how you would reduce those errors.", "rubric": "70 points. Question and hypothesis: 10 points. Variables and control: 14 points. Procedure and trials: 14 points. Data table and graph plan: 10 points. Biomolecule connection: 10 points. Sources of error: 8 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Design a Fair Experiment$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Searching Out the Matter$j$, $j${"prompt": "Scientists search out the details of creation. Write a post of at least 120 words that (1) explains in your own words why a fair test changes only one variable at a time, (2) describes one property of water that is important for life and tells how it helps living things, (3) tells how careful, honest observation can strengthen your respect for the Creator, and (4) connects your answer to Psalm 19:1, which says, The heavens declare the glory of God; and the firmament sheweth his handywork. Then write a respectful reply of at least 40 words to another student, or answer this question: Why is an experiment with only one trial not very convincing? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Searching Out the Matter$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: How Scientists Ask and Test Questions$j$, $j${"questions": [{"q": "A hypothesis in science is best described as:", "options": ["A final conclusion", "A testable explanation or prediction", "A proven fact that never changes", "A guess that cannot be tested"]}, {"q": "Which statement is a testable hypothesis?", "options": ["Seeds are beautiful", "If seeds get more water, then more of them will sprout", "Seeds are the best part of a plant", "Everyone should plant seeds"]}, {"q": "Why do scientists share their procedures and results?", "options": ["To make the hypothesis true", "To avoid using evidence", "So no one else can do the experiment", "So others can repeat and check the work"]}, {"q": "A scientific theory is:", "options": ["A well tested explanation supported by much evidence", "The same as a hunch", "A random guess", "An opinion with no data"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: How Scientists Ask and Test Questions$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,0}'::int[], array[$j$A hypothesis is a testable explanation or prediction that evidence can support or reject.$j$,$j$Only the first statement predicts something that can be measured.$j$,$j$Repeatable work that others can check builds trust in the evidence.$j$,$j$In science a theory is supported by a large body of evidence, such as cell theory.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: How Scientists Ask and Test Questions$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Variables, Data and Evidence$j$, $j${"questions": [{"q": "The factor a scientist changes on purpose is the:", "options": ["Conclusion", "Dependent variable", "Independent variable", "Controlled variable"]}, {"q": "The factor that is measured to see the effect is the:", "options": ["Independent variable", "Control group", "Dependent variable", "Hypothesis"]}, {"q": "On a graph, the independent variable is usually placed on the:", "options": ["y axis", "x axis", "key", "title"]}, {"q": "Which is the best reason to use a large sample size?", "options": ["Controls are not needed", "The hypothesis is always right", "The experiment is faster", "Results are more trustworthy"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Variables, Data and Evidence$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,1,3}'::int[], array[$j$The independent variable is the one factor changed on purpose.$j$,$j$The dependent variable responds to the change and is what you measure.$j$,$j$The independent variable goes on the horizontal x axis.$j$,$j$More subjects and trials reduce the effect of chance.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Variables, Data and Evidence$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Water: The Molecule of Life$j$, $j${"questions": [{"q": "A water molecule is polar because:", "options": ["Oxygen has a slight negative charge and hydrogen a slight positive charge", "It has no charge at all", "It has only one atom", "It is made of carbon"]}, {"q": "Water molecules sticking to each other is called:", "options": ["Dissolving", "Adhesion", "Evaporation", "Cohesion"]}, {"q": "Ice floats because solid water is:", "options": ["Heavier than liquid water", "A gas", "Less dense than liquid water", "Not made of molecules"]}, {"q": "A solution with a pH of 3 is:", "options": ["Basic", "Neutral", "Acidic", "Pure water"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Water: The Molecule of Life$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,2,2}'::int[], array[$j$Unequal sharing of electrons gives the oxygen end a slight negative charge.$j$,$j$Cohesion is attraction between molecules of the same substance.$j$,$j$Hydrogen bonds hold ice in a spaced pattern that is less dense.$j$,$j$A pH below 7 is acidic.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Water: The Molecule of Life$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: The Four Biomolecules of Life$j$, $j${"questions": [{"q": "The monomer of a protein is the:", "options": ["Fatty acid", "Glucose", "Amino acid", "Nucleotide"]}, {"q": "Which biomolecule stores and passes on genetic instructions?", "options": ["Nucleic acids", "Water", "Lipids", "Carbohydrates"]}, {"q": "An enzyme is best described as a:", "options": ["Protein that speeds up a reaction", "Sugar used for fuel", "Mineral that is used up", "Lipid that stores energy"]}, {"q": "Iodine solution turns dark blue black when it touches:", "options": ["Protein", "Oil", "Water", "Starch"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: The Four Biomolecules of Life$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,0,3}'::int[], array[$j$Proteins are chains of amino acids.$j$,$j$DNA and RNA are nucleic acids.$j$,$j$Enzymes are protein catalysts that lower the energy needed to start a reaction.$j$,$j$Iodine is the standard test for starch.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: The Four Biomolecules of Life$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: The Nature of Science and the Chemistry of Life$j$, $j${"questions": [{"q": "Which question could a scientist test with an experiment?", "options": ["Does the amount of salt change how fast seeds sprout?", "Should people love gardens?", "Which flower is the prettiest?", "Is spring better than fall?"]}, {"q": "In an experiment, the control group:", "options": ["Does not receive the treatment and is used for comparison", "Is changed in every way", "Is the only group measured", "Receives the largest treatment"]}, {"q": "A student measures plant height after giving different amounts of water. Height is the:", "options": ["Controlled variable", "Dependent variable", "Independent variable", "Hypothesis"]}, {"q": "The special properties of water mainly result from:", "options": ["Carbon atoms", "Its taste", "Its color", "Hydrogen bonds between polar molecules"]}, {"q": "A solution with pH 9 is:", "options": ["Acidic", "Basic", "Neutral", "Pure acid"]}, {"q": "Which pairing of biomolecule and monomer is correct?", "options": ["Lipid and amino acid", "Protein and amino acid", "Carbohydrate and nucleotide", "Nucleic acid and glucose"]}, {"q": "An enzyme stops working when it is denatured because:", "options": ["It becomes a sugar", "It grows larger", "It turns into water", "Its shape changes and the substrate no longer fits"]}, {"q": "Starch can be detected with:", "options": ["A ruler", "Iodine solution", "Litmus paper only", "Salt water"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: The Nature of Science and the Chemistry of Life$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,1,3,1,1,3,1}'::int[], array[$j$Only the first question can be answered with measurements.$j$,$j$The control group provides a baseline for comparison.$j$,$j$Height is measured as the response.$j$,$j$Hydrogen bonds cause cohesion, high specific heat and the other properties.$j$,$j$A pH above 7 is basic.$j$,$j$Proteins are built from amino acids.$j$,$j$The active site shape is needed to bind the substrate.$j$,$j$Iodine turns dark blue black with starch.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: The Nature of Science and the Chemistry of Life$j$ on conflict (item_id) do nothing;
